"use client"

// Central client-side state for the Mini App: onboarding flow, preferences,
// saved jobs, and the currently viewed job. All persistence goes through
// lib/api.ts.

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react"
import type { Job, Preferences } from "@/lib/types"
import {
  getEffectiveTelegramUser,
  initTelegram,
  type TelegramUser,
} from "@/lib/telegram"
import {
  getSavedJobs,
  getUserProfile,
  removeSavedJob,
  saveJob,
  saveUserPreferences,
} from "@/lib/api"

export type Screen =
  | "checking"
  | "welcome"
  | "onboarding"
  | "loading"
  | "jobs"
  | "saved"
  | "profile"
  | "job-details"
  | "edit-preferences"

interface AppState {
  screen: Screen
  preferences: Preferences
  savedJobIds: string[]
  savedJobs: Job[]
  selectedJobId: string | null
  telegramUser: TelegramUser | null
  error: string | null
  // navigation
  goTo: (screen: Screen) => void
  startOnboarding: () => void
  completeOnboarding: (prefs: Preferences) => Promise<void>
  editPreferences: () => void
  savePreferences: (prefs: Preferences) => Promise<void>
  finishLoading: () => void
  openJob: (id: string) => void
  closeJob: () => void
  // saved jobs
  isSaved: (id: string) => boolean
  toggleSaved: (id: string, job?: Job) => void
  // errors
  clearError: () => void
}

const AppContext = createContext<AppState | null>(null)

const EMPTY_PREFS: Preferences = { jobType: null, field: null, location: null }

export function AppProvider({ children }: { children: ReactNode }) {
  const [screen, setScreen] = useState<Screen>("checking")
  const [preferences, setPreferences] = useState<Preferences>(EMPTY_PREFS)
  const [savedJobIds, setSavedJobIds] = useState<string[]>([])
  const [savedJobs, setSavedJobs] = useState<Job[]>([])
  const [selectedJobId, setSelectedJobId] = useState<string | null>(null)
  const [previousScreen, setPreviousScreen] = useState<Screen>("jobs")
  const [telegramUser, setTelegramUser] = useState<TelegramUser | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Remembers the last profile save so identical saves within 10s are skipped.
  const lastSaveRef = useRef<{ key: string; at: number } | null>(null)
  const isDuplicateSave = useCallback((prefs: Preferences) => {
    const key = JSON.stringify(prefs)
    const last = lastSaveRef.current
    if (last && last.key === key && Date.now() - last.at < 10_000) return true
    lastSaveRef.current = { key, at: Date.now() }
    return false
  }, [])

  useEffect(() => {
    let cancelled = false

    async function init() {
      initTelegram()
      const user = getEffectiveTelegramUser()
      if (cancelled) return
      setTelegramUser(user)

      if (!user) {
        setScreen("welcome")
        return
      }

      // Load saved jobs ONCE at startup and keep them in state.
      // The Saved screen reads from here instead of fetching again.
      getSavedJobs(user.id).then((jobs) => {
        if (cancelled) return
        setSavedJobs(jobs)
        setSavedJobIds(jobs.map((j) => j.id))
      })

      const profile = await getUserProfile(user.id)
      if (cancelled) return

      const hasSavedPrefs =
        profile && (profile.job_type || profile.field || profile.location)

      if (hasSavedPrefs && profile) {
        setPreferences({
          jobType: profile.job_type,
          field: profile.field,
          location: profile.location,
        })
        setScreen("jobs")
      } else {
        setScreen("welcome")
      }
    }

    init()
    return () => {
      cancelled = true
    }
  }, [])

  const goTo = useCallback((next: Screen) => setScreen(next), [])

  const startOnboarding = useCallback(() => setScreen("onboarding"), [])

  const completeOnboarding = useCallback(
    async (prefs: Preferences) => {
      setPreferences(prefs)
      setScreen("loading")
      if (isDuplicateSave(prefs)) return // same save just happened, skip the webhook
      try {
        await saveUserPreferences(prefs, telegramUser?.id, telegramUser ?? undefined)
      } catch (err) {
        setError(err instanceof Error ? err.message : "Couldn't save your preferences.")
      }
    },
    [telegramUser, isDuplicateSave],
  )

  const savePreferences = useCallback(
    async (prefs: Preferences) => {
      setPreferences(prefs)
      if (isDuplicateSave(prefs)) {
        setScreen("loading")
        return
      }
      try {
        await saveUserPreferences(prefs, telegramUser?.id, telegramUser ?? undefined)
      } catch (err) {
        setError(err instanceof Error ? err.message : "Couldn't save your preferences.")
        throw err
      }
      setScreen("loading")
    },
    [telegramUser, isDuplicateSave],
  )

  const editPreferences = useCallback(() => setScreen("edit-preferences"), [])

  const finishLoading = useCallback(() => setScreen("jobs"), [])

  const openJob = useCallback((id: string) => {
    setSelectedJobId(id)
    setScreen((current) => {
      if (current !== "job-details") setPreviousScreen(current)
      return "job-details"
    })
  }, [])

  const closeJob = useCallback(() => {
    setSelectedJobId(null)
    setScreen(previousScreen)
  }, [previousScreen])

  const clearError = useCallback(() => setError(null), [])

  const isSaved = useCallback((id: string) => savedJobIds.includes(id), [savedJobIds])

  // One webhook call per tap. No side effects inside state updaters,
  // and no refetch of the saved list afterwards.
  const toggleSaved = useCallback(
    (id: string, job?: Job) => {
      const uid = telegramUser?.id
      if (savedJobIds.includes(id)) {
        setSavedJobIds((p) => p.filter((x) => x !== id))
        setSavedJobs((p) => p.filter((j) => j.id !== id))
        void removeSavedJob(id, uid)
      } else {
        setSavedJobIds((p) => [...p, id])
        if (job) setSavedJobs((p) => [...p, job])
        void saveJob(id, uid)
      }
    },
    [savedJobIds, telegramUser],
  )

  const value = useMemo<AppState>(
    () => ({
      screen,
      preferences,
      savedJobIds,
      savedJobs,
      selectedJobId,
      telegramUser,
      error,
      goTo,
      startOnboarding,
      completeOnboarding,
      editPreferences,
      savePreferences,
      finishLoading,
      openJob,
      closeJob,
      isSaved,
      toggleSaved,
      clearError,
    }),
    [
      screen,
      preferences,
      savedJobIds,
      savedJobs,
      selectedJobId,
      telegramUser,
      error,
      goTo,
      startOnboarding,
      completeOnboarding,
      editPreferences,
      savePreferences,
      finishLoading,
      openJob,
      closeJob,
      isSaved,
      toggleSaved,
      clearError,
    ],
  )

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useApp(): AppState {
  const ctx = useContext(AppContext)
  if (!ctx) throw new Error("useApp must be used within AppProvider")
  return ctx
}