// API service layer for KhmerGigs.
//
// Every function here calls a real n8n webhook. Google Sheets (via n8n) is
// the source of truth for jobs and users — this file never fabricates or
// caches job data client-side.

import type { Job, Preferences, RecommendedJob, UserProfile } from "./types"
import type { TelegramUser } from "./telegram"

// Base URL for the n8n API. Read from env so it can be configured per
// environment (production vs. preview) without code changes.
//
// Set NEXT_PUBLIC_API_BASE_URL in Vercel → Project Settings → Environment
// Variables. Falls back to the known production n8n instance so local dev
// still works if the env var isn't set.
export const API_BASE =
  process.env.NEXT_PUBLIC_API_BASE_URL ?? "https://khmergigs.app.n8n.cloud"

const SAVE_PREFERENCES_URL = `${API_BASE}/webhook/kg/user/preferences`
const GET_PROFILE_URL = `${API_BASE}/webhook/kg/user/profile`
const RECOMMENDATIONS_URL = `${API_BASE}/webhook/kg/jobs/recommendations`
const JOB_DETAILS_URL = `${API_BASE}/webhook/kg/jobs/details`
const SAVE_JOB_URL = `${API_BASE}/webhook/kg/saved/add`
const REMOVE_SAVED_JOB_URL = `${API_BASE}/webhook/kg/saved/remove`
const GET_SAVED_JOBS_URL = `${API_BASE}/webhook/kg/saved/list`

/** POSTs JSON with a timeout so a hung n8n instance can't freeze the UI. */
async function postJson<T>(url: string, body: unknown, timeoutMs = 10000): Promise<T> {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), timeoutMs)
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: controller.signal,
    })
    if (!res.ok) {
      throw new Error(`Request to ${url} failed with status ${res.status}`)
    }
    return (await res.json()) as T
  } finally {
    clearTimeout(timer)
  }
}

export interface SavePreferencesResult {
  success: boolean
  userId: string
}

/**
 * Persist the user's onboarding preferences to the n8n "User" sheet.
 * @param preferences the selected job type, field and location
 * @param telegramUserId Telegram user id — the primary identity key
 * @param telegramUser optional first_name/username to keep the sheet row current
 */
export async function saveUserPreferences(
  preferences: Preferences,
  telegramUserId?: number,
  telegramUser?: Pick<TelegramUser, "first_name" | "username">,
): Promise<SavePreferencesResult> {
  const now = new Date().toISOString()

  try {
    await postJson(SAVE_PREFERENCES_URL, {
      telegram_user_id: telegramUserId ? String(telegramUserId) : "",
      first_name: telegramUser?.first_name ?? "",
      username: telegramUser?.username ?? "",
      job_type: preferences.jobType,
      field: preferences.field,
      location: preferences.location,
      created_at: now,
      updated_at: now,
    })
    return {
      success: true,
      userId: telegramUserId ? String(telegramUserId) : "",
    }
  } catch (err) {
    console.error("[api] saveUserPreferences failed", err)
    throw new Error("Couldn't save your preferences. Please try again.")
  }
}

/**
 * Loads a previously saved profile for this Telegram user, if one exists.
 * Requires an n8n webhook at POST /webhook/kg/user/profile that looks up
 * the row by Telegram User ID in the User sheet (see setup notes).
 *
 * Returns null both when the user has no saved profile yet AND when the
 * request fails — either way, the caller should fall back to onboarding
 * rather than blocking the user.
 */
export async function getUserProfile(telegramUserId: number): Promise<UserProfile | null> {
  try {
    const data = await postJson<{ success: boolean; user: UserProfile | null }>(
      GET_PROFILE_URL,
      { telegram_user_id: String(telegramUserId) },
    )
    return data.user ?? null
  } catch (err) {
    console.error("[api] getUserProfile failed", err)
    return null
  }
}

/**
 * Fetch job recommendations for the given preferences, sorted by match score.
 * The n8n workflow behind this does the filtering + OpenAI ranking — the
 * frontend just displays whatever list comes back (5–10 real jobs, fewer if
 * fewer good matches exist; never fabricated).
 */
export async function getRecommendations(
  prefs: Preferences,
  telegramUserId?: number,
): Promise<RecommendedJob[]> {
  try {
    const data = await postJson<{ success: boolean; jobs: RecommendedJob[] }>(
      RECOMMENDATIONS_URL,
      {
        telegram_user_id: telegramUserId ? String(telegramUserId) : "",
        job_type: prefs.jobType,
        field: prefs.field,
        location: prefs.location,
      },
      20000, // ranking can take longer than a simple save/lookup
    )
    return data.jobs ?? []
  } catch (err) {
    console.error("[api] getRecommendations failed", err)
    throw new Error("We couldn't load recommendations right now. Please try again.")
  }
}

/** Fetch full details for a single job by id. Real jobs only — never mock data. */
export async function getJobDetails(id: string): Promise<Job | null> {
  try {
    const data = await postJson<{ success: boolean; job: Job | null }>(JOB_DETAILS_URL, {
      id,
    })
    return data.job ?? null
  } catch (err) {
    console.error("[api] getJobDetails failed", err)
    throw new Error("We couldn't load this job right now. Please try again.")
  }
}

/** Save (bookmark) a job for the current user, persisted to User_Interactions. */
export async function saveJob(id: string, telegramUserId?: number): Promise<{ success: boolean }> {
  try {
    await postJson(SAVE_JOB_URL, {
      telegram_user_id: telegramUserId ? String(telegramUserId) : "",
      job_id: id,
      action: "saved",
      timestamp: new Date().toISOString(),
    })
    return { success: true }
  } catch (err) {
    console.error("[api] saveJob failed", err)
    return { success: false }
  }
}

/** Remove a previously saved job, persisted to User_Interactions. */
export async function removeSavedJob(
  id: string,
  telegramUserId?: number,
): Promise<{ success: boolean }> {
  try {
    await postJson(REMOVE_SAVED_JOB_URL, {
      telegram_user_id: telegramUserId ? String(telegramUserId) : "",
      job_id: id,
      action: "removed",
      timestamp: new Date().toISOString(),
    })
    return { success: true }
  } catch (err) {
    console.error("[api] removeSavedJob failed", err)
    return { success: false }
  }
}

/**
 * Fetch the full job records the user has saved. The backend resolves ids to
 * real job rows itself — the frontend never needs its own copy of job data.
 */
export async function getSavedJobs(
  telegramUserId?: number,
): Promise<Job[]> {
  if (!telegramUserId) return []
  try {
    const data = await postJson<{ success: boolean; jobs: Job[] }>(GET_SAVED_JOBS_URL, {
      telegram_user_id: String(telegramUserId),
    })
    return data.jobs ?? []
  } catch (err) {
    console.error("[api] getSavedJobs failed", err)
    return []
  }
}